INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-empty-ride', 'south', 'the-felling-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-north-turning', 'south', 'the-stump-field', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-timber-stack', 'west', 'the-coppice-stools', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-felling-edge', 'door', 'The Felling Edge', 'The trees stop here as if a line had been drawn, and past it the ground is open, stumped and bright. Somebody cut this wood for a living, a long time ago, in rows. The rows are still there if you look along them.', 0, 0, 'wood', 0, -39, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-felling-edge', 'north', 'the-empty-ride', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-felling-edge', 'east', 'the-hauling-ride', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-felling-edge', 'west', 'the-brash-heaps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-stump-field', 'door', 'The Stump Field', 'Stumps to the edge of sight, each one cut level at the height of a man''s knee, each one grey and checked and soft at the heart. Saplings have come up between them, but not many. The ground has not forgiven the cutting yet.', 0, 0, 'wood', 0, -37, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stump-field', 'north', 'the-far-north-turning', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stump-field', 'south', 'the-saw-pit', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stump-field', 'west', 'the-hauling-ride', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stump-field', 'east', 'the-sawdust-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hauling-ride', 'door', 'The Hauling Ride', 'A broad ride cut straight through the stumps for dragging timber out, its floor still rutted deep where the trunks went down it on chains. The ruts hold water. They all run the same way.', 0, 0, 'wood', 0, -38, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hauling-ride', 'west', 'the-felling-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hauling-ride', 'east', 'the-stump-field', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-brash-heaps', 'door', 'The Brash Heaps', 'Heaps of lopped branches, the brash the fellers cut off and threw aside, piled higher than your head and grown through with bramble. Things live in them. The heaps tick and settle as you go by.', 0, 0, 'wood', 0, -40, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brash-heaps', 'east', 'the-felling-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-saw-pit', 'door', 'The Saw Pit', 'A long pit dug into the ground and lined with boards, gone green, where two men once sawed a trunk lengthways, one above and one below in the dust. The bottom of it is full of black water. A rusted dog-iron still bites the edge.', 0, 0, 'wood', 0, -37, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-saw-pit', 'north', 'the-stump-field', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-saw-pit', 'south', 'the-skid-road', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sawdust-floor', 'door', 'The Sawdust Floor', 'The ground here is not ground but sawdust, years of it, packed and rotted to a dark soft floor that gives under your boot and smells sweet. Nothing walks on it without leaving a print. The prints are not all old.', 0, 0, 'wood', 0, -36, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sawdust-floor', 'west', 'the-stump-field', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sawdust-floor', 'south', 'the-axe-stumps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-skid-road', 'door', 'The Skid Road', 'Logs laid crossways in the mud, side by side, to make a road the timber could be skidded over. Most have sunk. The ones that have not roll under your weight and throw you.', 0, 0, 'wood', 0, -37, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-skid-road', 'north', 'the-saw-pit', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-skid-road', 'west', 'the-bark-strip', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-axe-stumps', 'door', 'The Axe Stumps', 'Older stumps, cut by axe and not by saw, each one finished in a wedge-shaped point where the tree went over. They stand in a ring as if the fellers had worked round something in the middle. There is nothing in the middle.', 0, 0, 'wood', 0, -36, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-axe-stumps', 'north', 'the-sawdust-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-axe-stumps', 'south', 'the-cord-stacks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bark-strip', 'door', 'The Bark Strip', 'Bark lies in long curled sheets across the ground where it was peeled off the felled trunks for the tanners and never collected. It has dried to the shape of the trees it came off. It cracks like bone.', 0, 0, 'wood', 0, -38, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bark-strip', 'east', 'the-skid-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bark-strip', 'west', 'the-sawyers-bench', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cord-stacks', 'door', 'The Cord Stacks', 'Firewood cut to length and stacked in cords between stakes, row after row, the stakes gone over and the stacks slumped into long rotten mounds. Fungus has taken them. In the dark they would glow.', 0, 0, 'wood', 0, -36, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cord-stacks', 'north', 'the-axe-stumps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sawyers-bench', 'door', 'The Sawyer''s Bench', 'A trestle of split oak stands in a clearing of chips, its top worn hollow in the middle by a long working life. A whetstone lies under it in the leaves. Whoever sat here could see every way into the felling.', 0, 0, 'wood', 0, -39, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sawyers-bench', 'east', 'the-bark-strip', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sawyers-bench', 'west', 'the-wedge-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wedge-ground', 'door', 'The Wedge Ground', 'Iron wedges lie about in the grass here, rusted to the colour of the soil, dropped where they were driven out of the split logs. There are dozens of them. Nobody came back for a single one.', 0, 0, 'wood', 0, -40, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wedge-ground', 'east', 'the-sawyers-bench', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wedge-ground', 'north', 'the-split-oak', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-split-oak', 'door', 'The Split Oak', 'A great oak trunk lies along the ground split clean down its length into two halves, the wedges still in it, the halves sprung apart and gone silver. It was the last tree they cut. It was never moved.', 0, 0, 'wood', 0, -40, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-split-oak', 'south', 'the-wedge-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-split-oak', 'east', 'the-coppice-stools', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-coppice-stools', 'door', 'The Coppice Stools', 'Hazel cut back to the stool and left, and every stool has thrown up a dozen straight poles since, so the ground is a crowded grey thicket of stems all the same height. You go through it sideways. It closes up behind.', 0, 0, 'wood', 0, -39, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-coppice-stools', 'west', 'the-split-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-coppice-stools', 'east', 'the-timber-stack', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-ride', 'south', 'the-withy-holt', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-osier-beds', 'south', 'the-cut-osiers', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-withy-hut', 'west', 'the-peeling-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-withy-holt', 'door', 'The Withy Holt', 'Willow grown for cutting, row on row of stools sending up straight red-brown rods taller than a man, the ground between them wet and black. The rows were planted. They have gone their own way since.', 0, 0, 'wood', 0, -29, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-withy-holt', 'north', 'the-south-ride', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-withy-holt', 'south', 'the-soaking-pit', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cut-osiers', 'door', 'The Cut Osiers', 'The rods were cut here the last winter anybody worked the holt, and the stools have thrown up a ring of young shoots each, green and whippy and thick as fingers. The cut ends are all at one height. It is a long time since that height was new.', 0, 0, 'wood', 0, -30, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut-osiers', 'north', 'the-osier-beds', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut-osiers', 'south', 'the-willow-stools', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut-osiers', 'east', 'the-soaking-pit', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-soaking-pit', 'door', 'The Soaking Pit', 'A square pit full of brown water where the cut rods were stood to soak before they were peeled and bent. A bundle is still in it, upright, rotted to a black stump bound with rotten twine. The water does not move.', 0, 0, 'wood', 0, -29, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-soaking-pit', 'north', 'the-withy-holt', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-soaking-pit', 'west', 'the-cut-osiers', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-soaking-pit', 'south', 'the-bundle-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-willow-stools', 'door', 'The Willow Stools', 'Old willow stools, each a fat knuckled stump as wide as a cart wheel, grown together at the edges so the ground is a floor of root and bark with water under it. Step from stool to stool. Between them is deeper than it looks.', 0, 0, 'wood', 0, -30, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-willow-stools', 'north', 'the-cut-osiers', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-willow-stools', 'west', 'the-wet-ride', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bundle-ground', 'door', 'The Bundle Ground', 'A patch of firm ground where the cut withies were tied in bundles and stacked for carrying. The stakes are still in the ground in a row. The grass grows short and pale where the bundles lay, as if they were lifted yesterday.', 0, 0, 'wood', 0, -29, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bundle-ground', 'north', 'the-soaking-pit', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wet-ride', 'door', 'The Wet Ride', 'A ride runs through the holt, a straight cut between the rows, and the water has taken it so that walking it means wading. The willows lean in over it from both sides. Down at the end the light is green.', 0, 0, 'wood', 0, -31, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-ride', 'east', 'the-willow-stools', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-ride', 'north', 'the-pollard-line', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-pollard-line', 'door', 'The Pollard Line', 'A line of old pollard willows along a drain, each one cut back to a fat head at shoulder height and grown out into a wild crown of rods. Their trunks are hollow. One of them, someone has slept in.', 0, 0, 'wood', 0, -31, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pollard-line', 'south', 'the-wet-ride', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pollard-line', 'west', 'the-holt-drain', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-holt-drain', 'door', 'The Holt Drain', 'A straight drain dug to carry the water off the holt, its sides cut square and still mostly square, choked with weed and running slow. It goes as far as you can see in both directions. There is a plank across it, half sunk.', 0, 0, 'wood', 0, -32, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holt-drain', 'east', 'the-pollard-line', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holt-drain', 'west', 'the-osier-carr', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-osier-carr', 'door', 'The Osier Carr', 'The holt has gone back to carr here, willow and alder and sedge grown wild over the old rows, the water standing among them at every hour. It is darker than the rest. Something moves in it before you do.', 0, 0, 'wood', 0, -33, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-osier-carr', 'east', 'the-holt-drain', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-osier-carr', 'south', 'the-peeling-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-osier-carr', 'west', 'the-basket-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-peeling-bank', 'door', 'The Peeling Bank', 'A bank above the water where the soaked rods were peeled, the bark stripped and thrown down in heaps that have rotted to a soft brown mould. The bank is firm and dry. It is the one place in the holt you could sit.', 0, 0, 'wood', 0, -33, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peeling-bank', 'north', 'the-osier-carr', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peeling-bank', 'east', 'the-withy-hut', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-basket-ground', 'door', 'The Basket Ground', 'Half-made baskets lie in the grass here, the bases woven and the sides begun and never finished, gone grey and brittle. There are a dozen of them. Whoever made them stopped all at once.', 0, 0, 'wood', 0, -34, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basket-ground', 'east', 'the-osier-carr', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basket-ground', 'south', 'the-withy-drain', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-withy-drain', 'door', 'The Withy Drain', 'Where the drain meets the holt''s edge, a sluice of rotten boards held the water back once and holds a little of it still, a black pool on one side and wet mud on the other. The boards weep.', 0, 0, 'wood', 0, -34, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-withy-drain', 'north', 'the-basket-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-west-ride', 'west', 'the-paved-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-kitchen-range', 'north', 'the-road-ruts', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gate-arch', 'west', 'the-horse-pond', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-paved-road', 'door', 'The Paved Road', 'The stone road that ran under the arch runs on here, flags laid edge to edge and worn smooth in two grooves by wheels, the grass coming up through every joint. It goes the way the arch faced. Nobody comes along it any more.', 0, 0, 'wood', 0, -42, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-paved-road', 'east', 'the-west-ride', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-paved-road', 'north', 'the-stable-range', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-road-ruts', 'door', 'The Road Ruts', 'The paving gives out and the road goes on as two deep ruts in the turf, cut by iron tyres over years, so deep a boot goes in to the ankle. Water lies in them after rain. Prints lie in them after everything else.', 0, 0, 'wood', 0, -44, -7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-road-ruts', 'south', 'the-kitchen-range', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-road-ruts', 'east', 'the-outer-ditch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stable-range', 'south', 'the-paved-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stable-range', 'north', 'the-counterscarp', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-outer-ditch', 'door', 'The Outer Ditch', 'A broad ditch, the outer line of the gatehouse''s works, dry now and grassed, deep enough that you go down into it and cannot see out. Its sides were cut steep to stop a charge. They still slow a walk.', 0, 0, 'wood', 0, -43, -7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-outer-ditch', 'west', 'the-road-ruts', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-outer-ditch', 'east', 'the-barbican-footings', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-counterscarp', 'door', 'The Counterscarp', 'The far bank of the outer ditch, built up with the spoil and faced with stone that has mostly fallen in. From the top you can see down into the ditch along its whole length. Somebody once stood here to do exactly that.', 0, 0, 'wood', 0, -42, -6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-counterscarp', 'south', 'the-stable-range', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-counterscarp', 'north', 'the-barbican-footings', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-barbican-footings', 'door', 'The Barbican Footings', 'The footings of an outwork that stood in front of the arch, two lines of squared stone in the grass with a gap between for the road. The walls above them are gone. The gap is still the only easy way through.', 0, 0, 'wood', 0, -42, -7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-barbican-footings', 'west', 'the-outer-ditch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-barbican-footings', 'north', 'the-killing-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-barbican-footings', 'south', 'the-counterscarp', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-killing-ground', 'door', 'The Killing Ground', 'Open ground between the outer ditch and where the walls stood, kept clear on purpose once so that nothing could cross it unseen, and still clear now, the grass short and the trees held back. You are seen here. You can feel it.', 0, 0, 'wood', 0, -42, -8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-killing-ground', 'south', 'the-barbican-footings', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-killing-ground', 'west', 'the-guard-footings', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-killing-ground', 'east', 'the-pay-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-guard-footings', 'door', 'The Guard Footings', 'A square of stone footings no bigger than a cart, with a hearthstone in one corner black with old fire. A guard post stood here and watched the road. The hearth is cold. The view down the road is the same.', 0, 0, 'wood', 0, -43, -8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-guard-footings', 'east', 'the-killing-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-guard-footings', 'west', 'the-mounting-block', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-pay-stone', 'door', 'The Pay Stone', 'A squat stone by the road with a hollow cut in its top, worn smooth, where the coin was left and taken. The edge of the hollow is polished by hands. Nobody has paid anything here in a long time.', 0, 0, 'wood', 0, -41, -8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pay-stone', 'west', 'the-killing-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pay-stone', 'east', 'the-outer-bailey', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-mounting-block', 'door', 'The Mounting Block', 'Three stone steps up to nothing, standing alone in the grass by the road, built for climbing into a saddle. The top step is hollowed by boots. The horses are a long time gone.', 0, 0, 'wood', 0, -44, -8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mounting-block', 'east', 'the-guard-footings', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mounting-block', 'north', 'the-bailey-wall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-outer-bailey', 'door', 'The Outer Bailey', 'A wide enclosure of rough grass, banked all round, where the gatehouse kept its horses and its carts and its people when the gate was shut. The banks still hold the wind off. Inside them it is quieter than it should be.', 0, 0, 'wood', 0, -40, -8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-outer-bailey', 'west', 'the-pay-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-outer-bailey', 'north', 'the-rampart-walk', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bailey-wall', 'door', 'The Bailey Wall', 'A stretch of the bailey''s wall still stands to shoulder height, rough stone laid without mortar, with a walk along the inside where a man could stand and see over. Ivy has taken the top. The walk is still sound.', 0, 0, 'wood', 0, -44, -9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bailey-wall', 'south', 'the-mounting-block', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bailey-wall', 'north', 'the-old-palisade', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-rampart-walk', 'door', 'The Rampart Walk', 'The top of the old bank, flat and narrow and grassed, with the ditch on one side and the bailey on the other. It goes round in a long curve. Walk it far enough and you come back to where you started.', 0, 0, 'wood', 0, -40, -9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rampart-walk', 'south', 'the-outer-bailey', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rampart-walk', 'north', 'the-ward-ditch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-old-palisade', 'door', 'The Old Palisade', 'A line of oak stakes, sharpened once, set close in the top of a bank. Most have rotted off at the ground. The ones still standing are black and hard as iron and lean outward, still pointed at whoever was coming.', 0, 0, 'wood', 0, -44, -10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-palisade', 'south', 'the-bailey-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-palisade', 'east', 'the-turning-bay', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ward-ditch', 'door', 'The Ward Ditch', 'An inner ditch, narrower and deeper than the outer, cut close under where the gatehouse wall stood. It holds water at the bottom, green and still. The sides are slick. You would not climb out of it in a hurry.', 0, 0, 'wood', 0, -40, -10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ward-ditch', 'south', 'the-rampart-walk', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ward-ditch', 'west', 'the-tilt-yard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-turning-bay', 'door', 'The Turning Bay', 'A wide paved place where the road broadened so a cart could turn before the arch, the flags laid in a fan and worn in an arc by wheels going round. Weeds have taken the joints. The arc is still plain.', 0, 0, 'wood', 0, -43, -10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turning-bay', 'west', 'the-old-palisade', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turning-bay', 'south', 'the-horse-pond', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-tilt-yard', 'door', 'The Tilt Yard', 'A long level strip of ground, straight as a rule, banked at both ends, where riders once ran at each other for practice or for show. The grass on it is different from the grass around. The ground remembers being flat.', 0, 0, 'wood', 0, -41, -10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tilt-yard', 'east', 'the-ward-ditch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tilt-yard', 'south', 'the-boundary-cross', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-horse-pond', 'door', 'The Horse Pond', 'A shallow pond with a cobbled ramp going down into it on one side, built for walking horses in to drink and cool their legs. The water is low and clear over the cobbles. Hoofprints at the edge, and not old.', 0, 0, 'wood', 0, -43, -9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-horse-pond', 'north', 'the-turning-bay', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-horse-pond', 'east', 'the-gate-arch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boundary-cross', 'door', 'The Boundary Cross', 'A stone cross stands by the road, the arms broken off and the shaft cut with the mark of whoever held this ground. It marked where their writ ran. The arch and this are all that is left of them.', 0, 0, 'wood', 0, -41, -9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-cross', 'north', 'the-tilt-yard', NULL);
