-- FIRST, BY HAND (the builder only adds).
-- THE GATES STEP BACK. Done by hand because the builder only adds: the three
-- wood gates' old doors onto the rides come out, and each gate moves on the map
-- to the middle of its ring. The Stable Range stays where it stands: the arch's
-- road now runs through it on the way in, instead of it hanging off the arch.
DELETE FROM exits WHERE (room_id = 'the-timber-stack' AND dir = 'south')
  OR (room_id = 'the-thin-soil' AND dir = 'north')
  OR (room_id = 'the-withy-hut' AND dir = 'north')
  OR (room_id = 'the-south-ride' AND dir = 'south')
  OR (room_id = 'the-gate-arch' AND dir IN ('east', 'south', 'north'))
  OR (room_id = 'the-stable-range' AND dir = 'south')
  OR (room_id = 'the-west-ride' AND dir = 'west')
  OR (room_id = 'the-well-court' AND dir = 'north');
UPDATE rooms SET map_x = -38, map_y = 6 WHERE id = 'the-timber-stack';
UPDATE rooms SET map_x = -32, map_y = 6 WHERE id = 'the-withy-hut';
